head.script:

scwin.onpageload = function() {
	requires("uiplugin.popup");

	var _dataObj = {
		type : "json",
		data : {},
		name : "paramData"
	};

	var options = {
		id : "popupTest",
		popupName : "팝업테스트",
		type :  "wframePopup",
		width : "560px",
		height : "400px",
		top :  "140px",
		left :  "500px",
		modal :  true,
		dataObject : _dataObj,
		alwaysOnTop :  false,
		useModalStack :  true,
		resizable :  true,
		useMaximize : false,
		className :  "",
		scrollbars : true,
		closeAction :"",
		popupUrl : "../popup"
	};



	$p.openPopup("popup_modal_userFilter_WESD-938_(WSQ-4919)_sub.xml" , options);
};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('_modal').style.display == 'block';
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popupTest_wframe_wq_uuid_6_column1_filter').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn')[1].click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popupTest_wframe_wq_uuid_6_item_0_selectbox_column1_button').click()");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popupTest_wframe_wq_uuid_6_item_0_selectbox_column1_itemTable_1').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popupTest_wframe_wq_uuid_6_btnConform_column1').click()");
	WebSquare.wUnit.addCommand("pause", "500");			
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
